    nodes = publisher['path']['nodes']
    P07_need(grid['startCell'] == nodes[0][0] and grid['endCell'] == nodes[-1][0] and (grid['endLayer'] == nodes[-1][1]), 'GRAPH_GRID_PATH_JOIN')
    masks = body['masks']
