        tuple_rows.append(','.join((str(value) for value in (index, parent, cell, x, y, layer, direction, vias, cost, heuristic, serial, key_value))))
        if index:
            previous = nodes[index - 1]
            if layer == previous[1]:
                dx, dy = (x - previous[2], y - previous[3])
