    work = body['work']
    work_names = ('advanceCalls', 'workSteps', 'copyEntries', 'comparisonEntries', 'geometryBytes', 'effectUnits', 'ordinaryQueries', 'goalCells', 'reachedPadChecks', 'encodedCells', 'pathNodes', 'pathEdgesVerified', 'tupleBytes', 'serializedUtf16Units', 'activeMillis')
    P07_keys(work, work_names, 'GRAPH_WORK_SCHEMA')
    P07_need(P07_integer(entry['elapsedToCloseNanos'], 1, P07_LIMITS['operationNanos']) and all((P07_integer(work[name]) for name in work_names)) and (work['advanceCalls'] > 0) and (work['workSteps'] > 0) and (work['copyEntries'] > 0) and (work['comparisonEntries'] > 0), 'GRAPH_WORK_VALUES')
    cursor_groups = [group for group in groups if group['graphCursorSteps'] > 0]
    cursor_steps = sum((group['graphCursorSteps'] for group in groups))
    P07_need(work['advanceCalls'] == len(cursor_groups) and work['workSteps'] == cursor_steps == sum(phase_work) and (work['ordinaryQueries'] == 2 * (2 * grid['height'] * (grid['width'] - 1) + 2 * grid['width'] * (grid['height'] - 1))) and (work['goalCells'] == grid['cells']) and (work['encodedCells'] == 3 * grid['cells']) and (work['pathNodes'] == graph_path['nodeCount']) and (work['pathEdgesVerified'] == graph_path['nodeCount'] - 1) and (work['geometryBytes'] == 2 * pub_before['geometryBytes']) and (work['tupleBytes'] == len(tuple_preimage)) and (work['serializedUtf16Units'] <= 1000000) and (work['activeMillis'] <= entry['elapsedToCloseNanos'] // 1000000), 'GRAPH_WORK_CONSERVATION')
    lower_bound_names = ('copyEntries', 'comparisonEntries', 'geometryBytes', 'effectUnits', 'ordinaryQueries', 'goalCells', 'reachedPadChecks', 'pathNodes', 'pathEdgesVerified', 'tupleBytes', 'serializedUtf16Units')
    P07_need(work['workSteps'] >= sum((work[name] for name in lower_bound_names)), 'GRAPH_WORK_LOWER_BOUND')
    P07_need(work['advanceCalls'] == len(cursor_groups) and all((group['graphCursorSteps'] <= 32768 for group in cursor_groups)), 'GRAPH_CURSOR_GROUP_CONSERVATION')
    body_raw = P07__top_level_value_bytes(raw, 'body')
    canonical_body = P07__canonical_graph_body(body)
    P07_need(body_raw == canonical_body and work['serializedUtf16Units'] == len(body_raw), 'GRAPH_BODY_CANONICAL_BYTES')
    integrity = document['integrity']
