    P07_keys(integrity, integrity_names, 'GRAPH_INTEGRITY_SCHEMA')
    P07_need(all((type(integrity[name]) is bool and integrity[name] is True for name in integrity_names)), 'GRAPH_INTEGRITY')
    limitations = document['limitations']
    limitations_names = ('model', 'lengthEligibilityOnly', 'legalSearchHistory', 'publicationQualified', 'layoutQualification', 'routeAdoption', 'playable100', 'fullPhysicalProof')
    P07_keys(limitations, limitations_names, 'GRAPH_LIMITATIONS_SCHEMA')
    P07_need(limitations['model'] == 'DIRECTED_PER_FACE_ORDINARY_EDGES' and type(limitations['lengthEligibilityOnly']) is bool and (limitations['lengthEligibilityOnly'] is True) and (limitations['legalSearchHistory'] == 'NOT_RUN') and (type(limitations['publicationQualified']) is bool) and (limitations['publicationQualified'] is False) and (type(limitations['layoutQualification']) is bool) and (limitations['layoutQualification'] is False) and (type(limitations['routeAdoption']) is bool) and (limitations['routeAdoption'] is False) and (type(limitations['playable100']) is int) and (limitations['playable100'] == 0) and (limitations['fullPhysicalProof'] == 'NOT_RUN'), 'GRAPH_LIMITATIONS')
    if header['mode'] == 'AUTHORED':
        P07_need(context['operation'] == 4 and context['attempt'] == 4 and (context['request'] == 0) and (context['pass'] == 1) and ((context['rootSeed'], context['placementSeed'], context['routingSeed']) == ('9007199254740993', '-6587958367974952701', '8445301674744508279')) and ((branch['ordinal'], branch['netVectorPosition'], branch['netId'], branch['startPadId'], branch['rootPadId'], branch['foundTerminalPadId'], branch['branchRecordGroup'], branch['reachedPadIds']) == (248, 28, 'OUT_F', 'RSH_F.1', 'CSTORE_F.2', 'CSTORE_F.2', 57, ['CSTORE_F.2'])) and (branch_row['snapshot']['terminalReason'] == 'FOUND') and ((source['target'], source['sourceKind'], source['policy'], source['initialLayerMask'], source['reachedPthPadIds']) == ('OUT_F', 'OUT_F_REJECTED_PUBLISHER_PATH', 'FULLER_TWO_LAYER', 3, [])) and ((grid['width'], grid['height'], grid['cells'], grid['originX'], grid['originY'], grid['pitch']) == (478, 309, 147702, 30, 30, 10)) and (pub_before == pub_after) and (len(pub_before['traces']) == 180) and (len(pub_before['holes']) == 48) and (pub_before['geometryBytes'] == 271606) and (pub_before['geometrySha256'] == 'cbc98315295693be7cddc31d0327f6f89e5819fedb2b4ad1d65a25e7decc2739') and ((graph_path['nodeCount'], graph_path['planarEdgeCount'], graph_path['transitionCount']) == (171, 170, 0)) and ((work['ordinaryQueries'], work['goalCells']) == (1178468, 147702)), 'GRAPH_AUTHORED_IDENTITY')
        start_pad = pads_by_id[branch['startPadId']]
        found_node = nodes[-1]
        path_length = sum((grid['pitch'] for left, right in zip(nodes, nodes[1:]) if left[1] == right[1]))
        direct = abs(start_pad['x'] - found_node[2]) + abs(start_pad['y'] - found_node[3])
        bends = 0
