def P07_validate_pad_census(pads, candidate):
    P07_need([p['padId'] for p in pads] == sorted({p['padId'] for p in pads}) and len({p['netId'] for p in pads}) == candidate['netCount'] and (len({p['componentId'] for p in pads}) == candidate['componentCount']), 'PAD_CENSUS')

def P07_validate_snapshot_shape(snapshot):
    P07_keys(snapshot, P07_SNAP_INTS + P07_SNAP_BOOLS + P07_SNAP_STRINGS, 'SNAPSHOT_SCHEMA')
    P07_need(all((P07_token(snapshot[n]) for n in ('netId', 'startPadId', 'rootPadId'))) and type(snapshot['terminalReason']) is str, 'SNAPSHOT_IDENTIFIERS')
    P07_need(all((P07_integer(snapshot[n], -2 ** 31, 2 ** 31 - 1) for n in P07_SNAP_INTS)) and all((type(snapshot[n]) is bool for n in P07_SNAP_BOOLS)), 'SNAPSHOT_TYPES')
    P07_need(all((P07_integer(snapshot[n], 0, 2 ** 31 - 1) for n in P07_SNAP_INTS if n not in ('startX', 'startY', 'rootX', 'rootY', 'initialManhattanDistance', 'minimumExploredManhattanDistance'))) and P07_integer(snapshot['initialManhattanDistance'], -1, 2 ** 31 - 1) and P07_integer(snapshot['minimumExploredManhattanDistance'], -1, 2 ** 31 - 1), 'SNAPSHOT_COUNT_DOMAIN')

def P07_audit_choices(branches, pads, arm):
    by_id = {p['padId']: p for p in pads}
    nets = {}
    for p in pads:
        nets.setdefault(p['netId'], []).append(p['padId'])
    states = {}
    seen = {}
    prior = None
    total = 0
    choices = []
    for row in branches:
        s = row['snapshot']
        P07_validate_snapshot_shape(s)
        p = s['pass']
        net = s['netId']
        P07_need(P07_integer(p, 0, 2) and net in nets and (s['terminalReason'] in ('FOUND', 'NO_PATH', 'TOTAL_SEARCH_LIMIT', 'BRANCH_SEARCH_LIMIT')), 'BRANCH_TERMINAL')
        P07_need(P07_integer(s['gridWidth'], 1, 250000) and P07_integer(s['gridHeight'], 1, 250000) and (s['gridWidth'] * s['gridHeight'] <= 250000) and P07_integer(s['prefixViaCount'], 0, 48), 'BRANCH_GRID_HOLES')
        P07_need(P07_integer(s['branchExpanded'], 0, 100000) and P07_integer(s['totalExpanded'], 0, 1000000) and P07_integer(s['expandedTop']) and P07_integer(s['expandedBottom']) and (s['expandedTop'] + s['expandedBottom'] == s['branchExpanded']), 'BRANCH_EXPANSIONS')
        total += s['branchExpanded']
        P07_need(total == s['totalExpanded'], 'CUMULATIVE_EXPANSIONS')
        if prior:
            ps = prior['snapshot']
            P07_need(p >= ps['pass'], 'PASS_ORDER')
            if p == ps['pass']:
                P07_need(ps['terminalReason'] == 'FOUND', 'FOLLOWED_FAILED_BRANCH')
                old = states[p, ps['netId']]
                old['reached'].append(ps['startPadId'])
                if net != ps['netId']:
                    P07_need(not old['remaining'], 'LEFT_UNFINISHED_NET')
        key = (p, net)
        if key not in states:
            P07_need(net not in seen.setdefault(p, set()), 'NET_REVISIT')
            seen[p].add(net)
            ordered = sorted(nets[net])
            P07_need(len(ordered) > 1, 'SINGLE_PAD_BRANCH')
            states[key] = {'reached': [ordered[0]], 'remaining': ordered[1:]}
        else:
            P07_need(prior is not None and prior['snapshot']['pass'] == p and (prior['snapshot']['netId'] == net), 'NET_REVISIT')
        state = states[key]
        remaining = state['remaining']
        reached = state['reached']
        P07_need(remaining and s['rootPadId'] == sorted(nets[net])[0] and (s['reachedPadCount'] == len(reached)), 'BRANCH_ROOT_REACHED')
        distances = {a: min((abs(by_id[a]['x'] - by_id[b]['x']) + abs(by_id[a]['y'] - by_id[b]['y']) for b in reached)) for a in remaining}
        nearest = min(remaining, key=lambda a: (distances[a], a))
        P07_need(s['startPadId'] == nearest, 'INDEPENDENT_CHOICE')
        for which in ('start', 'root'):
            pad = by_id.get(s[which + 'PadId'])
            P07_need(pad is not None and pad['netId'] == net and ((s[which + 'X'], s[which + 'Y']) == (pad['x'], pad['y'])), 'BRANCH_ENDPOINT')
        choices.append(dict(nearest=nearest, reached=tuple(reached), remaining=tuple(remaining)))
        remaining.remove(nearest)
        prior = row
    return (choices, total)

def P07_validate_diagnostic_clones(events, branches, branch_positions, pads, groups, arm):
    P07_need(arm != 0 or not events, 'DIAGNOSTIC_CLONE_PLAIN')
    pad_by_id = {row['padId']: row for row in pads}
    pads_by_net = {}
    for row in pads:
        pads_by_net.setdefault(row['netId'], set()).add(row['padId'])
    groups_by_id = {row['ordinal']: row for row in groups}
    seen_keys = set()
    matched = {i: [] for i in range(len(branches))}
    for position, row in events:
        key = (row['pass'], row['netId'], row['startPadId'], row['rootPadId'], row['faceIndex'])
        P07_need(key not in seen_keys, 'DIAGNOSTIC_CLONE_DUPLICATE')
        seen_keys.add(key)
        P07_need(row['netId'] in pads_by_net and row['startPadId'] in pad_by_id and (row['rootPadId'] in pad_by_id) and (pad_by_id[row['startPadId']]['netId'] == row['netId']) and (pad_by_id[row['rootPadId']]['netId'] == row['netId']), 'DIAGNOSTIC_CLONE_CENSUS')
        group = groups_by_id.get(row['group'])
        P07_need(group is not None and group['phase'] == 'ADVANCE' and (group['p07Slices'] == 1) and (group['accounting'] == 'MEASURED') and (row['ownerSteps'] <= group['p07Steps']), 'DIAGNOSTIC_CLONE_GROUP')
        candidates = []
        for i, branch in enumerate(branches):
            snapshot = branch['snapshot']
            if (snapshot['pass'], snapshot['netId'], snapshot['startPadId'], snapshot['rootPadId'], snapshot['prefixViaCount']) == (row['pass'], row['netId'], row['startPadId'], row['rootPadId'], row['prefixViaCount']):
                candidates.append(i)
        P07_need(len(candidates) == 1, 'DIAGNOSTIC_CLONE_BRANCH_MATCH')
        branch_index = candidates[0]
        P07_need(position < branch_positions[branch_index], 'DIAGNOSTIC_CLONE_ORDER')
        matched[branch_index].append((position, row))
    for i, branch in enumerate(branches):
        snapshot = branch['snapshot']
        branch_events = matched[i]
        if snapshot['relaxedBoundStarted']:
            P07_need(snapshot['relaxedBoundComplete'] is True and all((snapshot[name] is True for name in P07_DIAGNOSTIC_BOUND_PROOFS)), 'DIAGNOSTIC_CLONE_PROOF')
        expected = snapshot['relaxedBoundStarted'] and snapshot['prefixViaCount'] < P07_LIMITS['holeCap']
        if expected:
            P07_need([row['faceIndex'] for _, row in branch_events] == [0, 1] and sum((row['ownerSteps'] for _, row in branch_events)) == 2, 'DIAGNOSTIC_CLONE_PAIR')
        else:
            P07_need(not branch_events, 'DIAGNOSTIC_CLONE_UNEXPECTED')
    P07_need(len(events) <= 2 * 3 * (len(pads) - len(pads_by_net)), 'DIAGNOSTIC_CLONE_CAP')

def P07_validate_operation(raw, entry, source_sha, wire_sha, arm, run_id, kind):
    P07_need(raw and len(raw) <= P07_LIMITS['receiptBytes'] and raw.endswith(b'\n') and (b'\r' not in raw), 'RECEIPT_ENCODING_SIZE')
    lines = raw.splitlines(keepends=True)
    P07_need(all((len(x) <= P07_LIMITS['lineBytes'] and x != b'\n' for x in lines)), 'LINE_SIZE_EMPTY')
    rows = [P07_strict_json(x[:-1]) for x in lines]
    h = rows[0]
    P07_keys(h, ('record', 'group', 'schema', 'runId', 'mode', 'operation', 'arm', 'sourceManifestSha256', 'wireSha256', 'candidate', 'limits'), 'HEADER_SCHEMA')
    P07_need(h['record'] == 'HEADER' and P07_integer(h['group'], 0, 0) and (h['schema'] == P07_SCHEMA) and (h['runId'] == run_id) and P07_integer(h['operation'], 0, 4) and (h['operation'] == arm) and (h['sourceManifestSha256'] == source_sha) and (h['wireSha256'] == wire_sha) and (h['limits'] == P07_LIMITS), 'HEADER_IDENTITY')
    P07_keys(h['arm'], ('id', 'api', 'strategy', 'netOrderStrategy', 'observed', 'publisherCapture', 'graphCapture'), 'ARM_SCHEMA')
    P07_need(tuple((h['arm'][x] for x in ('id', 'api', 'strategy', 'netOrderStrategy', 'observed', 'publisherCapture'))) == P07_ARMS[arm] and type(h['arm']['observed']) is bool and (type(h['arm']['publisherCapture']) is bool) and (type(h['arm']['graphCapture']) is bool), 'ARM_IDENTITY')
    graph_capture_enabled = h['arm']['graphCapture']
    if arm != 4 or kind != 'READER_FIXTURE':
        P07_need(graph_capture_enabled is (arm == 4 and kind == 'AUTHORED'), 'ARM_GRAPH_CAPTURE')
    c = h['candidate']
    P07_keys(c, ('rootSeed', 'placementSeed', 'routingSeed', 'variant', 'layoutVersion', 'dependencyEpoch', 'componentCount', 'padCount', 'netCount', 'traceWidthProfile'), 'CANDIDATE_SCHEMA')
    for name in ('rootSeed', 'placementSeed', 'routingSeed'):
        P07_need(type(c[name]) is str and P07_re.fullmatch('0|-?[1-9][0-9]*', c[name]) is not None and (-2 ** 63 <= int(c[name]) < 2 ** 63), 'SEED_TRANSPORT')
    P07_need(c['layoutVersion'] == 26 and c['dependencyEpoch'] == 'tsj-generation-dependencies-v28' and (c['traceWidthProfile'] == 'ROLE_WIDTHS') and P07_integer(c['padCount'], 2, 1024) and P07_integer(c['netCount'], 1, c['padCount'] - 1) and P07_integer(c['componentCount'], 1, c['padCount']), 'CANDIDATE_VALUES')
    if kind == 'AUTHORED':
        P07_need(h['mode'] == 'AUTHORED' and tuple((c[x] for x in ('rootSeed', 'placementSeed', 'routingSeed'))) == ('9007199254740993', '-6587958367974952701', '8445301674744508279') and (c['variant'] == 'SEPARATE') and (c['componentCount'] == 100) and (c['padCount'] == 246), 'AUTHORED_CANDIDATE')
    else:
        P07_need(h['mode'] == 'TINY_CANARY' and c['variant'] == 'TINY' and (tuple((c[x] for x in ('rootSeed', 'placementSeed', 'routingSeed'))) == ('42', '5526715536693200536', '4493419427463069983')), 'TINY_CANDIDATE')
    pads = []
    branches = []
    groups = []
    result = None
    current_group = 0
    group_bytes = 0
    group_callbacks = 0
    group_pads = 0
    group_diagnostic_clones = 0
    group_net_orders = 0
    group_publisher_chunks = 0
    group_publisher_results = 0
    branch_positions = []
    diagnostic_events = []
    net_order_rows = []
    net_order_positions = []
    publisher_chunks = []
    publisher_result = None
    publisher_result_line = None
    publisher_payload_bytes = 0
    graph_chunks = []
    graph_result = None
    graph_result_line = None
    graph_payload_bytes = 0
    publisher_output_started = False
    publisher_capture_closed = False
    graph_output_started = False
    graph_capture_closed = False
    graph_cursor_started = False
    group_graph_chunks = 0
    group_graph_results = 0
    branch_seen = False
    report_seen = False
    report_closed = False
    pass_one_seen = False
    for line_index, (row, line) in enumerate(zip(rows[:-1], lines[:-1])):
        P07_need(not report_closed, 'TRAILING_REPORT_RECORD')
        P07_need(type(row) is dict and type(row.get('record')) is str, 'RECORD_TYPE')
        typ = row['record']
        if result is not None:
            P07_need(typ == 'GROUP', 'CAPTURE_AFTER_RESULT')
        source_record = typ in ('PAD', 'BRANCH', 'NET_ORDER', 'DIAGNOSTIC_CLONE')
        if graph_capture_enabled and graph_cursor_started and (not graph_capture_closed):
            P07_need(not source_record, 'GRAPH_CAPTURE_SOURCE_INTERLEAVING')
        capture_closed = graph_capture_closed if graph_capture_enabled else publisher_capture_closed
        if (publisher_output_started or publisher_result is not None) and (not capture_closed):
            allowed_output = ('PUB_CHUNK', 'PUB_RESULT', 'GRAPH_CHUNK', 'GRAPH_RESULT', 'RESULT', 'GROUP') if graph_capture_enabled else ('PUB_CHUNK', 'PUB_RESULT', 'RESULT', 'GROUP')
            P07_need(typ in allowed_output, 'CAPTURE_OUTPUT_INTERLEAVING')
        if typ == 'HEADER':
            P07_need(row is h, 'EXTRA_HEADER')
